            output: "f(a, b);",
            errors: [{ messageId: "unexpectedWhitespace", type: "CallExpression" }]
        },
        {
            code: "f.b ();",
            output: "f.b();",
            errors: [
                {
                    messageId: "unexpectedWhitespace",
                    type: "CallExpression",
                    column: 4,
                    line: 1,
                    endColumn: 4,
                    endLine: 1
                }
            ]
        },
        {
            code: "f.b().c ();",
            output: "f.b().c();",
            errors: [
                {
                    messageId: "unexpectedWhitespace",
                    type: "CallExpression",
                    column: 8,
                    line: 1,
                    endColumn: 8,
                    endLine: 1
                }
            ]
        },
        {
            code: "f() ()",
            output: "f()()",
            errors: [{ messageId: "unexpectedWhitespace", type: "CallExpression" }]
        },
        {
            code: "(function() {} ())",
            output: "(function() {}())",
            errors: [{ messageId: "unexpectedWhitespace", type: "CallExpression" }]
        },
        {
            code: "var f = new Foo ()",
            output: "var f = new Foo()",
            errors: [{ messageId: "unexpectedWhitespace", type: "NewExpression" }]
        },
        {
            code: "f ( (0) )",
            output: "f( (0) )",
            errors: [{ messageId: "unexpectedWhitespace", type: "CallExpression" }]
        },
        {
            code: "f(0) (1)",
            output: "f(0)(1)",
            errors: [{ messageId: "unexpectedWhitespace", type: "CallExpression" }]
        },
        {
            code: "(f) (0)",
            output: "(f)(0)",
            errors: [{ messageId: "unexpectedWhitespace", type: "CallExpression" }]
        },
        {
            code: "f ();\n t   ();",
            output: "f();\n t();",
            errors: [
                { messageId: "unexpectedWhitespace", type: "CallExpression" },
                { messageId: "unexpectedWhitespace", type: "CallExpression" }
            ]
        },
        {
            code: "import (source);",
            output: "import(source);",
            parserOptions: { ecmaVersion: 2020 },
            errors: [{ messageId: "unexpectedWhitespace", type: "ImportExpression" }]
        },

        // https://github.com/eslint/eslint/issues/7787
        {
            code: "f\n();",
            output: null, // no change
            errors: [{ messageId: "unexpectedWhitespace", type: "CallExpression" }]
        },
        {
            code: "f\r();",
            output: null, // no change
            errors: [{ messageId: "unexpectedWhitespace", type: "CallExpression" }]
        },
        {
            code: "f\u2028();",
            output: null, // no change
            errors: [{ messageId: "unexpectedWhitespace", type: "CallExpression" }]
        },
        {
            code: "f\u2029();",
            output: null, // no change
            errors: [{ messageId: "unexpectedWhitespace", type: "CallExpression" }]
        },
        {
            code: "f\r\n();",
            output: null, // no change
            errors: [{ messageId: "unexpectedWhitespace", type: "CallExpression" }]
        },
        {
            code: "import\n(source);",
